def check(args, got):
    s = args[0]
    if not isinstance(got, str):
        return False

    def has_dup(length):
        if length == 0:
            return True
        mod, base = (1 << 61) - 1, 131
        power = pow(base, length, mod)
        h, seen = 0, {}
        for i, ch in enumerate(s):
            h = (h * base + ord(ch)) % mod
            if i >= length:
                h = (h - ord(s[i - length]) * power) % mod
            if i >= length - 1:
                start = i - length + 1
                for j in seen.get(h, ()):
                    if s[j:j + length] == s[start:start + length]:
                        return True
                seen.setdefault(h, []).append(start)
        return False

    lo, hi = 0, len(s) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if has_dup(mid):
            lo = mid
        else:
            hi = mid - 1
    if len(got) != lo:
        return False
    first = s.find(got)
    return first != -1 and s.find(got, first + 1) != -1
